import {spawn} from 'node:child_process';
import {fileURLToPath} from 'node:url';
/** Only fixture gateway frames cross IPC; the child owns its actual signer/state/stores/permissions. */
export async function sourceProcess(root:string,peerId:string,deliver:(frame:Record<string,unknown>)=>void,attach:(feed:(frame:Record<string,unknown>)=>void)=>void){
 const child=spawn(process.execPath,['--import','tsx',fileURLToPath(new URL('./material-input-source-worker.ts',import.meta.url))],{cwd:process.cwd(),env:{HOME:root,TMPDIR:root,PATH:'/usr/bin:/bin',LANG:'en_US.UTF-8'},stdio:['ignore','ignore','pipe','ipc']});
 let started!:()=>void,lastStage='module-load';const startedPromise=new Promise<void>(resolve=>started=resolve);let counter=0,closed=false,closing:Promise<void>|undefined;const pending=new Map<number,{resolve:(value:any)=>void;reject:(error:Error)=>void;timer:ReturnType<typeof setTimeout>}>();
 const exited=new Promise<void>((resolve,reject)=>{child.once('error',reject);child.once('exit',(code)=>{for(const call of pending.values()){clearTimeout(call.timer);call.reject(Error('Source worker exited'));}pending.clear();if(code===0)resolve();else reject(Error('Source worker exit '+code));});});exited.catch(()=>{});
 child.stderr!.on('data',()=>{}); // Never relay potential source body/credential diagnostics.
 child.on('message',(message:any)=>{if(message.type==='worker-ready'){started();return;}if(message.type==='stage'){lastStage=message.stage;return;}if(message.type==='frame'){deliver(message.frame);return;}if(message.type!=='reply')return;const call=pending.get(message.id);if(!call)return;pending.delete(message.id);clearTimeout(call.timer);if(message.error)call.reject(Object.assign(Error('Source worker '+message.error.stage),{code:message.error.code}));else call.resolve(message.value);});
 const request=(method:string,input:unknown,timeout=30000,type='request'):Promise<any>=>{if(closed||!child.connected)return Promise.reject(Error('Source worker closed'));if(pending.size>=16)return Promise.reject(Error('Source worker capacity'));const id=++counter;return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{pending.delete(id);reject(Error('Source worker command deadline '+method+' stage '+lastStage));},timeout);pending.set(id,{resolve,reject,timer});child.send({type,id,method,input},error=>{if(!error)return;const call=pending.get(id);if(!call)return;pending.delete(id);clearTimeout(timer);reject(error);});});};
 const close=()=>closing??=(async()=>{try{if(child.connected)await request('close',{},25000,'close');closed=true;let timer:ReturnType<typeof setTimeout>|undefined;try{await Promise.race([exited,new Promise<never>((_,reject)=>timer=setTimeout(()=>reject(Error('Source worker exit deadline')),3000))]);}finally{if(timer)clearTimeout(timer);}}finally{closed=true;if(child.exitCode===null){child.kill('SIGKILL');await exited.catch(()=>{});}for(const call of pending.values()){clearTimeout(call.timer);call.reject(Error('Source worker closed'));}pending.clear();}})();
 const feed=(frame:Record<string,unknown>)=>{if(!closed&&child.connected)child.send({type:'frame',frame});};attach(feed);
 try{let timer:ReturnType<typeof setTimeout>|undefined;try{await Promise.race([startedPromise,new Promise<never>((_,reject)=>timer=setTimeout(()=>reject(Error('Source worker module startup deadline')),5000))]);}finally{if(timer)clearTimeout(timer);}const evidence=await request('bootstrap',{root,peerId},10000);return {pid:child.pid!,epoch:evidence.epoch as string,screen:evidence.screen as string,request,call:(path:string,body:unknown)=>request('call',{path,body}),feed,close};}catch(error){await close().catch(()=>{});throw error;}
}
